/** Declared order — independent of the object's key order in the constants. */
const ORDER: SocialKey[] = ["facebook", "instagram", "x", "youtube", "linkedin", "threads"];

export default function SocialLinks({ className = "" }: { className?: string }) {
    const links = ORDER.map((key) => ({ key, url: COMPANY_DETAILS.social[key], ...MARKS[key] })).filter(
        (l) => l.url.length > 0,
    );

    if (links.length === 0) return null;

    return (
        <ul className={`flex flex-wrap items-center gap-3 ${className}`}>
            {links.map((l) => (
                <li key={l.key}>
                    <a
                        href={l.url}
                        target="_blank"
                        // noopener/noreferrer: these leave our origin to a third party.
                        rel="noopener noreferrer me"
                        aria-label={`${COMPANY_DETAILS.brandName} on ${l.label}`}
                        className="inline-flex text-muted-foreground transition-colors hover:text-foreground"
                    >
                        <svg
                            viewBox="0 0 24 24"
                            aria-hidden="true"
                            focusable="false"
                            fill="currentColor"
                            className="size-5"
                        >
                            <path d={l.path} />
                        </svg>
                    </a>
                </li>
            ))}
        </ul>
    );
}
